#!/usr/bin/env python3
# ============================================================
# scan_diff.py — 两次 sdc-run.sh scan 的矩阵差分分析
# 用法: python3 scan_diff.py <dir1(matrix.tsv)> <dir2(matrix.tsv)>
# 输出: (1) 全差异单元 (2) fail 单元的核→簇/NUMA 映射 (3) 确认复测命令
# 设计: 捕获 fail 时五要素快速定位（核定位/用例/条件对比）
# ============================================================
import sys, re, subprocess

def load(path):
    rows = {}
    cores = None
    for line in open(path):
        parts = line.rstrip("\n").split("\t")
        if parts[0] == "test":
            cores = [int(c) for c in parts[1:]]
        else:
            rows[parts[0]] = dict(zip(cores, parts[1:]))
    return cores, rows

def topo(core):  # 核→(簇代表, NUMA node)  sysfs 缺拓扑时回退 /4 簇
    cl = "-"
    for f in ("cluster_cpus_list", "die_cpus_list"):
        try:
            t = open("/sys/devices/system/cpu/cpu%d/%s" % (core, f)).read().strip()
            cl = t.split("-")[0].split(",")[0]; break
        except OSError:
            continue
    if cl == "-":
        cl = str(core // 4 * 4)
    node = "-"
    for n in range(8):
        try:
            spec = open("/sys/devices/system/node/node%d/cpulist" % n).read().strip()
            for part in spec.split(","):
                if "-" in part:
                    a, b = map(int, part.split("-"))
                    if a <= core <= b: return cl, str(n)
                elif int(part) == core:
                    return cl, str(n)
        except OSError:
            continue
    return cl, node

def main():
    cores1, m1 = load(sys.argv[1])
    cores2, m2 = load(sys.argv[2])
    common = sorted(set(cores1) & set(cores2))
    tests = sorted(set(m1) & set(m2))
    print("# 差分: %s (%d核) vs %s (%d核), 共同 %d 核 %d 用例\n"
          % (sys.argv[1], len(cores1), sys.argv[2], len(cores2), len(common), len(tests)))
    diffs, fails = [], []
    for t in tests:
        for c in common:
            v1, v2 = m1[t].get(c, "-"), m2[t].get(c, "-")
            if v1 != v2:
                diffs.append((t, c, v1, v2))
                if v2 == "fail" or (v1 != "fail" and v2 not in ("pass", "skip", "-")):
                    fails.append((t, c, v1, v2))
    if not diffs:
        print("两轮矩阵完全一致（无状态迁移）")
        return 0
    print("## 状态迁移 (%d 处)\n" % len(diffs))
    for t, c, v1, v2 in diffs:
        print("- %s core%d: %s → %s" % (t, c, v1, v2))
    if fails:
        print("\n## fail 定位与确认命令\n")
        for t, c, v1, v2 in fails:
            cl, node = topo(c)
            print("- %s core%d (簇%s/NODE%s): %s → %s" % (t, c, cl, node, v1, v2))
        cores_f = sorted({c for _, c, _, _ in fails})
        tests_f = sorted({t for t, _, _, _ in fails})
        print("\n确认复测: cd /home/sdc/wangxu/sdcshield && bash scripts/run/sdc-run.sh scan "
              "--cores %s --tests %s --t 60s --par 4 --out ~/sdc-run/scan-confirm-$(date +%%m%%d-%%H%%M)"
              % (",".join(map(str, cores_f)), ",".join(tests_f)))
    return 1 if fails else 0

if __name__ == "__main__":
    sys.exit(main())

