#!/usr/bin/env python3
# timing_zscore.py — 扫描目录的每用例耗时 z-score 边缘性检测
# 用法: python3 timing_zscore.py <scan_dir> [阈值σ, 缺省3]
# 输出: |z|>阈值的 (核,用例) 列表——时序离群=潜在水银核早期信号
import sys, glob, re, statistics as st
d, thr = sys.argv[1], float(sys.argv[2]) if len(sys.argv) > 2 else 3.0
# test → {core: 累计runtime}
data = {}
for f in glob.glob(d + "/core_*.yaml"):
    core = int(re.search(r"core_(\d+)", f).group(1))
    cur = None
    for line in open(f, errors="replace"):
        m = re.match(r"^- test: (\S+)", line)
        if m: cur = m.group(1); data.setdefault(cur, {}).setdefault(core, 0.0)
        m = re.match(r"^  test-runtime: ([0-9.]+)", line)
        if m and cur: data[cur][core] += float(m.group(1))
out = []
for t, cores in sorted(data.items()):
    if len(cores) < 10: continue
    vals = list(cores.values()); mu, sd = st.mean(vals), st.pstdev(vals)
    if sd == 0: continue
    for c, v in cores.items():
        z = (v - mu) / sd
        if abs(z) > thr: out.append((abs(z), t, c, v, mu))
out.sort(reverse=True)
print("# %s: %d 用例 × %d 核, 阈值 %.1fσ" % (d, len(data), len(next(iter(data.values()))), thr))
if not out: print("无时序离群核"); sys.exit(0)
for z, t, c, v, mu in out[:30]:
    print("z=%+.1f %s core%d: %.0fms (均值 %.0fms)" % (z, t, c, v, mu))
PY
