173	static int ssl_sm3sm4_run(struct test *test, int cpu)
174	{
175	    struct sm_test_data *d = (struct sm_test_data *)test->data;
176	
177	    /* randomization hardening H7': per-thread copy of the (small) struct —
178	     * the shared d is only read; plaintext and goldens live in this
179	     * thread's copy and are re-rolled every iteration.  plaintext/
180	     * golden_ciphertext 是堆指针: 整结构体浅拷贝后必须换成线程私有
181	     * 缓冲, 否则 127 线程共享写同一块内存 = 假失败。 */
182	    struct sm_test_data local_d;
183	    memcpy(&local_d, d, sizeof(local_d));   /* key/iv/data_size/golden_sm3 */
184	    local_d.plaintext = (uint8_t *)malloc(local_d.data_size);
185	    local_d.golden_ciphertext = (uint8_t *)malloc(local_d.data_size);
186	    if (!local_d.plaintext || !local_d.golden_ciphertext) {
187	        free(local_d.plaintext);
188	        free(local_d.golden_ciphertext);
189	        return EXIT_SKIP;
190	    }
191	    const size_t SM_DATA_SIZE = local_d.data_size;
192	
193	    /* Per-thread work buffers, allocated once outside the loop (no
194	     * offsets needed, the cipher/digest work itself is the stress, same
195	     * as the ipsec EVP tests). */
196	    uint8_t *ciphertext = (uint8_t *)malloc(SM_DATA_SIZE);
197	    uint8_t *decrypted = (uint8_t *)malloc(SM_DATA_SIZE);
198	    uint8_t *digest = (uint8_t *)malloc(SM3_DIGEST_SIZE);
199	
200	    int outlen = 0;
201	
202	    TEST_LOOP(test, 256) {
203	        /* Re-roll: fresh plaintext + same-iteration golden through the
204	         * same EVP path for this thread's data. */
205	        memset_random(local_d.plaintext, SM_DATA_SIZE);
206	        int g_len = 0;
207	        sm4_cbc_encrypt(local_d.sm4_key, local_d.sm4_iv, local_d.plaintext,
208	                        local_d.golden_ciphertext, SM_DATA_SIZE, &g_len);
209	        if (g_len != (int)SM_DATA_SIZE)
210	            report_fail_msg("golden SM4-CBC encryption produced %d bytes, expected %zu (padding surprise)",
211	                            g_len, SM_DATA_SIZE);
212	        sm3_digest(local_d.plaintext, SM_DATA_SIZE, local_d.golden_sm3);
213	
214	        /* 1. Re-encrypt the plaintext and compare against golden */
215	        sm4_cbc_encrypt(local_d.sm4_key, local_d.sm4_iv, local_d.plaintext, ciphertext,
216	                        SM_DATA_SIZE, &outlen);
217	        if (outlen != (int)SM_DATA_SIZE)
218	            report_fail_msg("SM4-CBC encryption produced %d bytes, expected %zu (padding surprise)",
219	                            outlen, SM_DATA_SIZE);
220	        memcmp_or_fail(ciphertext, local_d.golden_ciphertext, SM_DATA_SIZE,
221	                       "sm4-cbc ciphertext mismatch");
222	
223	        /* 2. Decrypt the golden ciphertext, verify roundtrip */
224	        sm4_cbc_decrypt(local_d.sm4_key, local_d.sm4_iv, local_d.golden_ciphertext, decrypted,
225	                        SM_DATA_SIZE, &outlen);
226	        if (outlen != (int)SM_DATA_SIZE)
227	            report_fail_msg("SM4-CBC decryption produced %d bytes, expected %zu (padding surprise)",
228	                            outlen, SM_DATA_SIZE);
229	        memcmp_or_fail(decrypted, local_d.plaintext, SM_DATA_SIZE,
230	                       "sm4-cbc roundtrip mismatch");
231	
232	        /* 3. Recompute the SM3 digest and compare against golden */
233	        sm3_digest(local_d.plaintext, SM_DATA_SIZE, digest);
234	        memcmp_or_fail(digest, local_d.golden_sm3, SM3_DIGEST_SIZE,
235	                       "sm3 digest mismatch");
236	    }
237	
238	
239	    free(local_d.plaintext);
240	    free(local_d.golden_ciphertext);
241	    free(ciphertext);
242	    free(decrypted);
243	    free(digest);
244	    return EXIT_SUCCESS;
245	}
